const googleDocs = $input.all().map((item) => item.json);
const whatsappMessages = $("when message received")
  .all()
  .map((item) => item.json);

const date = new Date();
const formattedDate = `${date.getMonth() + 1} ${date.getDate()}, ${date.getFullYear()}`;

const docText = googleDocs[0].content.split("\n").join(" ");

const body = whatsappMessages[0].messages[0].text.body;

const finalPrompt = `Today's date is: ${formattedDate}\n\n${docText}\n\nUser's question:\n${body}`;

return { finalPrompt };

// within24h?  – run once per item
// Meta (WhatsApp) timestamp arrives as seconds since epoch
const lastTs = Number($('when message received').first().json.messages[0].timestamp) * 1000;   // → ms
const withinWindow = Date.now() - lastTs < 24 * 60 * 60 * 1000;

return [{ json: { withinWindow, answer: $json.answer, userId: $json.userId } }];

// cleanAnswer – run once per item
let txt = $('AI Agent').first().json.output || '';

// 0. Find the hidden 'send samples' tag and remove it from the reply.
//    Done first, because step 1 below strips underscores.
const TAG = /\[\s*SEND[\s_-]?SAMPLES\s*\]|\bSEND_SAMPLES\b/;
const sendSamples = TAG.test(txt);
txt = txt.replace(new RegExp(TAG.source, 'g'), ' ').replace(/[ \t]{2,}/g, ' ').trim();

// 1. Remove bold / italic / strike markers
txt = txt.replace(/[*_~]+/g, '');

// 2. Convert [Texto](https://url) → Texto https://url
txt = txt.replace(/\[([^\]]+)\]\((https?:\/\/[^\s)]+)\)/g, '$1 $2');

// 3. Collapse 3+ blank lines
txt = txt.replace(/\n{3,}/g, '\n\n').trim();

// 4. Remove the unwanted source-reference preamble
txt = txt.replace(/^.*?based on the document you provided[,:]?\s*/i, '');

return [{ json: { answer: txt, sendSamples } }];

// Sample websites the bot sends when a customer asks to see examples.
// Edit this list to change the samples. Each image is one paid YCloud message.
const samples = [
  {
    link: 'https://twodazzle.com/screenshots/coffee.png',
    caption: 'Aroma: café & F&B website with an interactive menu, gallery and loyalty card. Live demo: https://seagreen-boar-725110.hostingersite.com/',
  },
  {
    link: 'https://twodazzle.com/demoimage/69f1c08c586b783673c6.png',
    caption: 'Ember & Flour: bakery & café website with a chalkboard-style menu, bake schedule and order-ahead form. Live demo: https://lightgoldenrodyellow-fly-598753.hostingersite.com/',
  },
  {
    link: 'https://twodazzle.com/demoimage/e2ab7a1df4eefbbe8c96.png',
    caption: 'Nano&Leaf: aquarium & aquascaping shop with fish, live plants and a stocking calculator. Live demo: https://floralwhite-yak-608385.hostingersite.com/',
  },
];

return samples.map((sample) => ({ json: sample }));

// Check admin command – the admin numbers below can switch the bot with
// "bot off", "bot on" or "bot status". Same logic as tests/admin-command.js in the project folder.
// To add or remove an admin, edit both lists here AND in tests/admin-command.js.
// Admin phone numbers: digits only, starting with the country code (60).
const ADMIN_PHONES = new Set([
  '601121164719', // +60 11-2116 4719
  '60173793976', // +60 17-379 3976
  '60175227289', // +60 17-522 7289
]);
// Admins' WhatsApp user IDs, for messages that arrive without a phone number.
const ADMIN_USER_IDS = new Set([
  'MY.1043893888664788', // +60 11-2116 4719
  'MY.1753389605737336', // +60 17-379 3976
  'MY.2654098115050149', // +60 17-522 7289 (uses a WhatsApp username, so its number is hidden)
]);
const COMMANDS = new Map([
  ['bot off', 'off'],
  ['bot on', 'on'],
  ['bot status', 'status'],
]);

function classify(trigger) {
  const m = (trigger.messages && trigger.messages[0]) || {};
  const c = (trigger.contacts && trigger.contacts[0]) || {};
  const phone = String(m.from || c.wa_id || '').replace(/[^0-9]/g, '');
  const userId = String(m.from_user_id || c.user_id || '').trim();
  const isAdmin = ADMIN_PHONES.has(phone) || ADMIN_USER_IDS.has(userId);
  const text =
    m.type === 'text' && m.text && typeof m.text.body === 'string'
      ? m.text.body.trim().toLowerCase().replace(/\s+/g, ' ')
      : '';
  const command = (isAdmin && COMMANDS.get(text)) || 'none';
  return { isAdmin, command };
}

const trigger = $input.first().json;
return [{ json: { ...trigger, ...classify(trigger) } }];

// Build admin reply – confirmation for the owner. Same logic as tests/admin-command.js in the project folder.
// `value` is what bot_settings holds now; anything other than 'false' (or no row) means ON.
function adminReply(command, value) {
  const isOn = value !== 'false';
  if (command === 'status') {
    return isOn
      ? 'ℹ️ Bot is currently ON. Send "bot off" to pause it.'
      : 'ℹ️ Bot is currently OFF. Send "bot on" to turn it back on.';
  }
  return isOn
    ? '✅ Bot is ON. It will answer customers again.'
    : '✅ Bot is OFF. Customers won\'t get auto-replies until you send "bot on".';
}

const command = $('Check admin command').first().json.command;
const value = $input.first().json.value;
return [{ json: { reply: adminReply(command, value) } }];
